using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{
static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=64000000};
static object Info(IZFeature f,IZPart part){object body;try{part.Update();body=part.GetBody(true).GetBoundingBox();}catch(Exception ex){body=ex.Message;}var b=(IZSizeBox)f;var p=((IZSceneElement)f).ParameterMgr;return new{dims_m=new[]{b.Length,b.Width,b.Height},aspect=b.ResizeAspectLock.ToString(),expressions=new[]{b.LengthExpression,b.WidthExpression,b.HeightExpression},parameters=Enumerable.Range(0,p.Count).Select(i=>new{name=p.GetParameter(i).Name,expr=p.GetParameter(i).Expression,value=p.GetParameter(i).Value}).ToArray(),bounds=body};}
static void T(IZSceneElement target,IZSceneElement source){target.SetTransformToParent(source.GetTransformToParent());}
public static int Run(string folder){var report=new Dictionary<string,object>();IZDoc own=null;bool passed=false;try{var q=(Dictionary<string,object>)J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Host changed");dynamic l=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)l.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");string copy=Path.Combine(folder,"probe_copy.ics");File.Copy((string)q["source"],copy,false);bool already;own=app.OpenFile2(copy,false,false,out already);if(already){own=null;throw new Exception("Already open");}var s=(IZSceneDoc)own;var u=(IZSceneDocUtility)s;var results=new List<object>();
foreach(int id in new[]{222,235}){var old=(IZPart)u.GetElementById(id);var f=((IZPartFeatureMgr)old).GetFeatureAt(0);var ex=(IZExtrudeFeature)f;var stages=new Dictionary<string,object>();stages["original"]=Info(f,old);var fresh=s.CreatePart();var profile=s.CreateProfile();ex.CrossSection.CopyCurvesTo(profile);var nf=((IZPartFeatureMgr)fresh).CreateExtrudeFeature(f.OperationType,false,ex.get_ExtrudeDistance(eZExtrudeDirectionType.Z_EXTRUDE_DIRECTION_FORWARD),ex.get_ExtrudeDistance(eZExtrudeDirectionType.Z_EXTRUDE_DIRECTION_BACKWARD),0,profile,eZFeatureProfileRelType.Z_FEATURE_PROFILE_ABSORB);stages["created"]=Info((IZFeature)nf,fresh);T((IZSceneElement)((IZExtrudeFeature)nf).CrossSection,(IZSceneElement)ex.CrossSection);T((IZSceneElement)nf,(IZSceneElement)f);stages["transformed"]=Info((IZFeature)nf,fresh);((IZSizeBox)nf).Reset(false);stages["reset"]=Info((IZFeature)nf,fresh);results.Add(new{id=id,stages=stages});}
report["profiles"]=results;passed=true;
}catch(Exception ex){report["error"]=ex.ToString();}finally{if(own!=null)try{((IZSceneDoc)own).SaveAs(Path.Combine(folder,"PROBE_ONLY.ics"),eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);own.Close2(true);}catch(Exception ex){report["cleanup_error"]=ex.ToString();}report["passed"]=passed;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(report));}return passed?0:1;}
}}
